"""Call Script (v111): John Montini's veteran final expense script inside the Clients CRM. The tab, the way in from a record and
from Today's pane, the guide's branches (lead info, the client's response), objection answers, notes saved to the record,
outcomes through the CRM, print, reset, the secure steps and phone width."""
import sys, os, time, json, subprocess
SP = '/tmp/claude-0/-home-claude/6e37954b-9c9e-57d7-b212-24d756de5469/scratchpad'; sys.path.insert(0, SP)
import lgx
from playwright.sync_api import sync_playwright
PORT = int(os.environ.get('PORT', 8851)); SITE = os.environ.get('SITE', SP + '/web/test/site_gs'); URL = 'http://127.0.0.1:%d/index.html' % PORT
SHOTS = SP + '/web/test/shots'; os.makedirs(SHOTS, exist_ok=True)
res = []
def ok(c, m, info=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ') + m + ('' if c else '  ' + str(info)[:500]), flush=True)
srv = subprocess.Popen(['python3', '-m', 'http.server', str(PORT), '--bind', '127.0.0.1'], cwd=SITE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
SAY = "(document.querySelector('#gscard .gs-say')||{}).innerText||''"
CARD = "(document.querySelector('#gscard')||{}).innerText||''"
def step(A, i):
    A.evaluate("i=>{GS.cur=i;GS.wrap=0;gsPaint()}", i); A.wait_for_timeout(120)
def chip(A, text):
    # exact text (the chips are shown in capitals by CSS, and 'VA' is also inside 'Private')
    assert A.evaluate("t=>{const b=[...document.querySelectorAll('#gscard .gs-chip')].find(x=>x.textContent===t);if(b)b.click();return !!b}", text), text
    A.wait_for_timeout(120)
try:
    with sync_playwright() as p:
        b = p.chromium.launch(executable_path='/opt/pw-browsers/chromium', args=['--no-sandbox', '--disable-webgl', '--no-proxy-server'])
        ctx = b.new_context(viewport={'width': 1366, 'height': 900}); ctx.add_init_script("try{localStorage.setItem('owq_gq','still')}catch(e){}")
        errs = []
        K = ctx.new_page(); K.goto('http://127.0.0.1:%d/keep.html' % PORT); K.wait_for_function('window.__FAKE')
        A = ctx.new_page(); A.on('pageerror', lambda e: errs.append(str(e)[:200]))
        A.add_init_script("window.__FAKE_SIGNIN=%s;" % json.dumps({'uid': 'uOwner', 'email': 'owner@example.com', 'displayName': 'Cole Leckey'}))
        A.goto(URL); A.wait_for_function("window.__FAKE", timeout=20000); A.evaluate("__FAKE.call('reset',{owner:'owner@example.com'})"); A.evaluate("sessionStorage.clear()"); A.reload()
        A.wait_for_function("OWQC.phase==='out'", timeout=30000); A.click('#owqgi'); A.wait_for_function("OWQC.phase==='in'", timeout=30000)
        lgx.login(A, 2); A.wait_for_timeout(1500)
        A.wait_for_function("typeof SYN!=='undefined'&&SYN.first&&typeof CRM!=='undefined'&&CRM.ready", timeout=40000)
        me = A.evaluate("WHO==='Agency Owner'?'Cole Leckey':WHO")
        # ---- the tab, before any client is picked
        A.evaluate("openTab('Clients','Call Script')"); A.wait_for_timeout(700)
        tabs = A.evaluate("(document.querySelector('.crm-tabs')||{}).innerText||''")
        ok('CALL SCRIPT' in tabs.upper() and A.evaluate("!!document.getElementById('gsv')"), 'Clients has a Call Script tab', tabs)
        ok(('my name is ' + me) in A.evaluate(SAY) and '[CLIENT NAME]' in A.evaluate(SAY), 'step 1 is John\'s opening with the caller\'s own name and a fill-in for the client', A.evaluate(SAY))
        ok('WHO ARE YOU CALLING?' in A.evaluate("document.getElementById('gsv').innerText").upper() and A.evaluate("NSUB['Clients'].indexOf('Call Script')>=0"), 'with no client it asks who you are calling (and the sidebar lists the tab)')
        ok(A.evaluate("GS_D.items.length") == 37 and A.evaluate("document.querySelectorAll('.gs-gp').length") == 5, 'all 37 steps in the 5 parts of the call', A.evaluate("GS_D.items.length"))
        # ---- a client, opened from the record
        cid = A.evaluate("(()=>{const c=crmCreate({name:'Mary Jones',phone:'412-555-0102',email:'mary@example.com',dob:'1950-03-04',state:'PA',city:'Pittsburgh',owner:WHO});return c.id})()"); A.wait_for_timeout(500)
        A.evaluate("id=>crmOpen(id)", cid); A.wait_for_timeout(700)
        ok(A.evaluate("!!document.querySelector('.crm-360 .gs-strip')"), 'the client record has a Call script strip')
        A.screenshot(path=SHOTS + '/gs_record.png', full_page=False)
        A.click('.crm-360 .gs-strip button'); A.wait_for_timeout(700)
        st = A.evaluate("({sub:SUB['Clients'],cid:GS.cid,dob:GS.dob,email:GS.email})")
        ok(st['sub'] == 'Call Script' and st['cid'] == cid and st['dob'] and st['email'], 'Open call script links the client and checks DOB and email from the record', st)
        ok(('Hi, Mary, my name is ' + me) in A.evaluate(SAY), 'the opening uses the client\'s first name', A.evaluate(SAY))
        cl = A.evaluate("document.querySelector('.gs-cl').innerText")
        ok('Mary Jones' in cl and 'Pittsburgh' in cl and A.evaluate("!!document.querySelector('.gs-cl a.call[href^=\"tel:\"]')"), 'the client card shows who and where, with a Call button', cl)
        A.screenshot(path=SHOTS + '/gs_step1.png', full_page=False)
        # ---- the guide's branches
        A.click("#gscard button:has-text('Complete & next')"); A.wait_for_timeout(300)
        ok(A.evaluate("GS.cur") == 1 and A.evaluate("GS.done").count(0) == 1 and 'Awesome, I have your date of birth as March 4, 1950. Is that correct?' in A.evaluate(SAY), 'Complete & next: confirm the DOB from the record', A.evaluate(SAY))
        A.click("label.gs-ck:has-text('questions it')"); A.wait_for_timeout(250)
        ok('I hear you, Mary. I do have your date of birth as March 4, 1950.' in A.evaluate(SAY), 'a client who questions the reason gets the softer wording', A.evaluate(SAY))
        A.click("label.gs-ck:has-text('I have DOB')"); A.wait_for_timeout(250)
        ok('I hear you, Mary. I do have your email as mary@example.com. Is that correct?' in A.evaluate(SAY), 'no DOB: confirm the email instead', A.evaluate(SAY))
        A.click("label.gs-ck:has-text('I have email')"); A.wait_for_timeout(250)
        ok('Before we get started, what’s your date of birth?' in A.evaluate(SAY) and 'DATE OF BIRTH' in A.evaluate(CARD).upper(), 'nothing on the lead: ask for the DOB (and a place to note it)', A.evaluate(CARD)[:300])
        A.evaluate("(()=>{GS.dob=true;GS.email=true;GS.resp='accept';gsPaint()})()"); step(A, 3)
        ok('And I have your email as mary@example.com. Is that still correct?' in A.evaluate(SAY), 'the remaining-information step confirms the email', A.evaluate(SAY))
        step(A, 5); ok('And you’re currently living in Pittsburgh, Pennsylvania. Is that correct?' in A.evaluate(SAY), 'city and state come from the record', A.evaluate(SAY))
        step(A, 7); say7 = A.evaluate(SAY)
        ok('[PHONE]' in say7 and '[VERIFIED NPN]' in say7 and ('My name is ' + me) in say7, 'contact info: your phone and NPN are fill-ins until you save them', say7)
        A.evaluate("(()=>{gsMeSet('ph','412-555-0199');gsMeSet('npn','1234567');gsPaint()})()"); A.wait_for_timeout(150)
        ok('412-555-0199' in A.evaluate(SAY) and '1234567' in A.evaluate(SAY), 'and are read out once saved (on this device)', A.evaluate(SAY))
        # ---- objections
        step(A, 0)
        obs = A.evaluate("[...document.querySelectorAll('#gscard .gs-ob>label')].map(l=>l.innerText.trim())")
        ok(obs == ['I never requested this', 'Not interested', 'I’m busy', 'Stop calling / remove me', 'I need to think about it'], 'the opening objections, as in the guide', obs)
        A.click("#gscard .gs-ob label:has-text('busy')"); A.wait_for_timeout(250)
        ok('Of course, I don’t want to interrupt your day.' in A.evaluate(CARD) and 'SUGGESTED RESPONSE' in A.evaluate(CARD).upper(), 'checking an objection reveals the suggested response', A.evaluate(CARD)[-400:])
        step(A, 22); t22 = A.evaluate("[...document.querySelectorAll('#gscard .gs-ob>label')].map(l=>l.innerText.trim())")
        ok(t22 == ['It costs too much', 'I can’t afford it', 'I need to think about it — before application', 'I need to think about it — after quotes / application'], 'between quotes and application both think-about-it answers show', t22)
        step(A, 20); c20 = A.evaluate(CARD)
        ok('SECURE STEP' in c20.upper() and A.evaluate("document.querySelectorAll('#gscard input:not([type=checkbox]),#gscard textarea').length") == 0 and 'Why do you need my Social Security number?' in c20, 'the Social Security step: answers to the objections, a secure-step note, nowhere to type a number', c20[:300])
        step(A, 29); ok('SECURE STEP' in A.evaluate(CARD).upper() and A.evaluate("document.querySelectorAll('#gscard input:not([type=checkbox]),#gscard textarea').length") == 0, 'the banking step has no place to type bank details')
        step(A, 0); A.click("#gscard .gs-ob label:has-text('Stop calling')"); A.wait_for_timeout(250)
        A.click("#gscard button:has-text('End call / honor request')"); A.wait_for_timeout(300)
        endt = A.evaluate("document.getElementById('gsw').innerText")
        ok(A.evaluate("GS.resp") == 'decline' and 'CLIENT DECLINED' in endt.upper() and 'I understand, Mary. Thank you for your time.' in endt and 'DO NOT CONTACT' in endt.upper(), 'Stop calling: End call shows the respectful close with Do not contact', endt[:300])
        A.click("#gsw button:has-text('Back to the script')"); A.wait_for_timeout(250)
        A.evaluate("(()=>{GS.obj={};gsPaint()})()")
        # ---- noting what the client says
        step(A, 4); chip(A, 'Army')
        step(A, 8); chip(A, 'Them and spouse')
        step(A, 9); chip(A, 'Both')
        step(A, 11); chip(A, 'VA'); chip(A, 'Private')
        step(A, 13); chip(A, 'No')
        step(A, 14); chip(A, 'Yes')
        step(A, 18); A.fill('#gscard textarea', 'Stroke 2019, on blood thinners')
        step(A, 21); chip(A, 'Own'); A.fill('#gscard input[type=number]', '60')
        for i, (bb, mm) in zip((22, 23, 24), (('15000', '89'), ('10000', '62'), ('5000', '35'))):
            step(A, i); A.locator('#gscard input[type=number]').nth(0).fill(bb); A.locator('#gscard input[type=number]').nth(1).fill(mm)
        step(A, 25); chip(A, 'Full Coverage')
        ok('I recommend Full Coverage because [SPECIFIC REASON]' in A.evaluate(SAY), 'the recommendation reads out the option you picked', A.evaluate(SAY))
        step(A, 26); chip(A, 'Full Coverage')
        step(A, 28); A.locator('#gscard input[type=text]').nth(0).fill('Jane Jones'); A.locator('#gscard input[type=text]').nth(1).fill('Daughter')
        cap = A.evaluate("JSON.parse(JSON.stringify(GS.cap))")
        ok(cap.get('branch') == 'Army' and cap.get('who') == 'Them and spouse' and cap.get('cov') == ['VA', 'Private'] and cap.get('h_stroke') == 'Yes' and cap.get('h_heartattack') == 'No' and cap.get('bud') == '60' and cap.get('fu_m') == '62' and cap.get('pick') == 'Full Coverage' and cap.get('bn') == 'Jane Jones', 'Note it keeps each answer', cap)
        # ---- the Today pane (shown on wide screens), before the call is logged
        A.set_viewport_size({'width': 1920, 'height': 1080}); A.wait_for_timeout(300)
        A.evaluate("id=>{CRM.ui.tsel=id;openTab('Clients','Today')}", cid); A.wait_for_timeout(800)
        ok(A.locator('.crm-pa .gs-pb').is_visible(), "Today's detail pane has a Call script button")
        A.screenshot(path=SHOTS + '/gs_today.png', full_page=False)
        A.click('.crm-pa .gs-pb'); A.wait_for_timeout(600)
        A.set_viewport_size({'width': 1366, 'height': 900}); A.wait_for_timeout(300)
        ok(A.evaluate("SUB['Clients']") == 'Call Script' and A.evaluate("GS.cid") == cid and A.evaluate("GS.cap.pick") == 'Full Coverage', 'it opens the same call (nothing lost)')
        # ---- finish: the progress, the wrap-up, saving to the record
        A.evaluate("(()=>{for(let i=0;i<GS_N;i++)if(GS.done.indexOf(i)<0)GS.done.push(i);GS.cur=GS_N-1;gsPaint()})()"); A.wait_for_timeout(200)
        A.click("#gscard button:has-text('Complete call')"); A.wait_for_timeout(300)
        wt = A.evaluate("document.getElementById('gsw').innerText")
        ok('ALL STEPS COMPLETE' in wt.upper() and '37 of 37 steps completed' in A.evaluate("document.querySelector('.gs-pg').innerText") and 'SERVED IN' in wt.upper() and 'Army' in wt and '$10,000 benefit at $62/mo' in wt, 'all 37 done: the wrap-up lists what the client said', wt[:600])
        A.screenshot(path=SHOTS + '/gs_wrap.png', full_page=True)
        A.click("#gsw button:has-text('Save notes only')"); A.wait_for_timeout(600)
        c = A.evaluate("id=>JSON.parse(JSON.stringify(crmGet(id)))", cid)
        inf = c.get('info') or {}
        ok(inf.get('goal') == 'Final expenses and money for family' and inf.get('house') == 'Own' and inf.get('budget') == '$60/mo', 'saved to the record: goal, home, comfortable payment', inf)
        ok('Yes: Stroke' in (inf.get('health') or '') and 'blood thinners' in (inf.get('health') or ''), 'and the health answers', inf.get('health'))
        ok(c.get('ap') == 744 and c.get('prod') == 'Final Expense' and inf.get('bname') == 'Jane Jones' and inf.get('brel') == 'Daughter', 'the chosen option sets the expected annual premium (62 x 12), product and beneficiary', [c.get('ap'), c.get('prod'), inf.get('bname')])
        ok('Veteran' in (c.get('tags') or []) and 'Spouse' in (c.get('tags') or []), 'tags: Veteran (served) and Spouse', c.get('tags'))
        ev = A.evaluate("id=>crmEvents(id).map(e=>({ty:e.ty,o:e.o||'',t:e.t||''}))", cid)
        ok(any(e['ty'] == 'note' and e['t'].startswith('Call script (37/37 steps)') for e in ev), 'a note with the call summary is on the timeline', ev[-3:])
        ok('Saved to Mary' in A.evaluate("document.getElementById('gsw').innerText"), 'the wrap-up says it was saved')
        A.click("#gsw .gs-outs button:has-text('Interested, follow up')"); A.wait_for_timeout(600)
        ev = A.evaluate("id=>crmEvents(id).map(e=>({ty:e.ty,o:e.o||'',t:e.t||''}))", cid)
        nx = A.evaluate("id=>{const t=crmNext(id);return t?t.t:''}", cid)
        ok(any(e['ty'] == 'call' and e['o'] == 'int' and 'Call script' in e['t'] for e in ev) and nx == 'Follow up on interest', 'Interested logs the call through the CRM and books the follow-up', [ev[-2:], nx])
        ok(A.evaluate("id=>crmGet(id).stage", cid) == 'contacted' and 'Logged: Interested' in A.evaluate("document.getElementById('gsw').innerText"), 'the stage moves to Contacted and the call shows as logged')
        # ---- print
        A.evaluate("(()=>{window.__pst=[];window.print=()=>{window.__printed=(window.__printed||0)+1;window.__pst.push(String(new Error().stack).slice(0,300))}})()"); A.evaluate("gsPrint()"); A.wait_for_timeout(300)
        pr = A.evaluate("(()=>{const e=document.getElementById('gsprint');return {n:e.querySelectorAll('article').length,t:e.innerText,cls:document.body.classList.contains('gs-print'),p:window.__printed||0}})()")
        ok(pr['n'] == 38 and pr['p'] == 1 and ('Hi, Mary, my name is ' + me) in pr['t'] and 'CALL NOTES' in pr['t'].upper(), 'Print: the whole script for Mary, with the call notes', [pr['n'], pr['p'], A.evaluate('window.__pst')])
        A.evaluate("document.body.classList.remove('gs-print')")
        # ---- switching clients with unsaved notes asks first; Reset clears the call
        cid2 = A.evaluate("(()=>{const c=crmCreate({name:'Bob Smith',phone:'412-555-0103',state:'OH',owner:WHO});return c.id})()")
        A.evaluate("(()=>{GS.cap.hob='fishing';gsPersist()})()")
        A.evaluate("id=>gsOpen(id)", cid2); A.wait_for_timeout(300)
        ok('has not been saved' in A.evaluate("(document.getElementById('md')||{}).innerText||''") and A.evaluate("GS.cid") == cid, 'opening another client with unsaved notes asks first')
        A.click('#md #yes'); A.wait_for_timeout(500)
        ok(A.evaluate("GS.cid") == cid2 and A.evaluate("GS.done.length") == 0 and not A.evaluate("GS.dob") and not A.evaluate("GS.email") and 'what’s your date of birth' in A.evaluate("(()=>{GS.cur=1;gsPaint();return " + SAY + "})()"), 'a new call for Bob: fresh progress, no DOB or email on his lead')
        ok(A.evaluate("JSON.parse(sessionStorage.getItem('owq_gs')).cid") == cid2, 'the call is kept in this tab (sessionStorage)')
        A.evaluate("gsResetAsk()"); A.click('#md #yes'); A.wait_for_timeout(300)
        ok(A.evaluate("GS.cid") is None and A.evaluate("GS.cur") == 0 and 'WHO ARE YOU CALLING?' in A.evaluate("document.getElementById('gsv').innerText").upper(), 'New client / Reset clears the call')
        # ---- the picker
        A.fill('#gsq', 'mary'); A.wait_for_timeout(250)
        ok('Mary Jones' in A.evaluate("document.getElementById('gspr').innerText"), 'Find a client searches the book')
        A.click('#gspr .gs-pi'); A.wait_for_timeout(300)
        ok(A.evaluate("GS.cid") == cid and A.evaluate("GS.dob"), 'picking links the client')
        # ---- palette entry
        ok(A.evaluate("(()=>{const L=[];crmCmds(L);return L.some(x=>x[0]==='Open call script')})()"), 'the command palette can open the call script')
        # ---- phone width
        A.set_viewport_size({'width': 390, 'height': 844}); A.wait_for_timeout(400); A.evaluate("go()"); A.wait_for_timeout(500)
        ov = A.evaluate("(()=>{const v=document.getElementById('gsv');return {doc:document.documentElement.scrollWidth,w:innerWidth,v:v?v.scrollWidth:0,vw:v?v.clientWidth:0}})()")
        ok(ov['doc'] <= ov['w'] + 1 and ov['v'] <= ov['vw'] + 1, 'phone width: nothing runs off the screen', ov)
        A.screenshot(path=SHOTS + '/gs_phone.png', full_page=False)
        A.set_viewport_size({'width': 1366, 'height': 900}); A.wait_for_timeout(300)
        ok(not errs, 'no page errors', errs)
        b.close()
finally:
    srv.terminate()
print('%d/%d' % (sum(res), len(res)))
